from bisect import bisect_left

def longest_increasing_subsequence(nums):
    """Return length of longest strictly increasing subsequence."""
    if not nums:
        return 0

    # O(n²) DP approach
    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def longest_increasing_subsequence_optimized(nums):
    """O(n log n) binary search approach using patience sorting."""
    if not nums:
        return 0

    tails = []  # tails[k] = smallest tail of all length-(k+1) subsequences

    for num in nums:
        pos = bisect_left(tails, num)
        if pos == len(tails):
            tails.append(num)
        else:
            tails[pos] = num

    return len(tails)
